#!/usr/bin/env python3
import argparse
import json
import socket
import sys
import pathlib

DEFAULT_HOST = "127.0.0.1"
DEFAULT_PORT = 8226

def send_code(host: str, port: int, code: str, timeout_s: float) -> str:
    """
    Send raw Python source to the Isaac Sim VS Code extension server and return
    the formatted response.  The server (isaacsim.code_editor.vscode) receives
    the raw bytes, executes them, and replies with a JSON object:
        {"status": "ok"|"error", "output": "...", ["traceback": [...], ...]}
    then closes the connection.
    """
    s = socket.create_connection((host, port), timeout=2.0)
    s.sendall(code.encode("utf-8"))
    s.settimeout(timeout_s)
    chunks = []
    while True:
        try:
            b = s.recv(65536)
        except socket.timeout:
            raise RuntimeError(
                f"Timed out after {timeout_s}s waiting for Isaac Sim response — "
                "execution may still be running. Retry with a larger timeout."
            )
        if not b:
            break
        chunks.append(b)
    s.close()
    data = b"".join(chunks)
    if not data:
        raise RuntimeError("No response received from Isaac Sim.")
    txt = data.decode("utf-8", errors="replace").strip()
    try:
        return format_response(json.loads(txt))
    except Exception:
        return txt + "\n"

def format_response(obj: dict) -> str:
    """
    Try to print stdout + traceback/error in a nice way.
    Different versions use different keys.
    """
    out_keys = ["output", "stdout", "result", "out"]
    tb_keys = ["traceback", "trace", "stderr", "error", "exception"]

    out = ""
    for k in out_keys:
        if k in obj and obj[k]:
            out = str(obj[k])
            break

    err = ""
    for k in tb_keys:
        if k in obj and obj[k]:
            err = str(obj[k])
            break

    # Some servers return {"status":"ok","output":"..."} etc.
    status = obj.get("status")
    parts = []
    if out:
        parts.append(out.rstrip("\n"))
    if err:
        # Separate stdout and error
        parts.append(err.rstrip("\n"))
    if not parts:
        # fall back to pretty JSON
        parts.append(json.dumps(obj, indent=2))
    return "\n".join(parts) + "\n"


def main() -> int:
    ap = argparse.ArgumentParser(
        description="Send Python code to a running Isaac Sim VS Code executor (default 127.0.0.1:8226)."
    )
    ap.add_argument("--host", default=DEFAULT_HOST)
    ap.add_argument("--port", default=DEFAULT_PORT, type=int)
    ap.add_argument("--timeout", default=10.0, type=float, help="seconds to wait for Isaac Sim to finish executing (default: 10)")
    g = ap.add_mutually_exclusive_group(required=False)
    g.add_argument("--file", type=pathlib.Path)
    g.add_argument("--code", type=str)
    g.add_argument("--stdin", action="store_true", help="read code from stdin")
    args = ap.parse_args()

    if not args.file and not args.stdin and not args.code:
        ap.error("one of --file, --code, or --stdin is required")

    if args.file or args.stdin or args.code:
        if args.file:
            code = args.file.read_text()
        elif args.stdin:
            code = sys.stdin.read()
        else:
            code = args.code

        try:
            msg = send_code(args.host, args.port, code, args.timeout)
        except OSError as e:
            sys.stderr.write(f"Connection failed: {e}\n")
            return 2
        except RuntimeError as e:
            sys.stderr.write(f"{e}\n")
            return 2

        sys.stdout.write(msg)
        if "Traceback (most recent call last)" in msg or "Error" in msg or "Exception" in msg:
            return 1

    return 0

if __name__ == "__main__":
    raise SystemExit(main())